package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import cpw.mods.fml.common.FMLCommonHandler;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.bag.*;import dev.industrialtechnology.client.*;import dev.industrialtechnology.core.*;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiMainMenu;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.network.play.server.S09PacketHeldItemChange;import net.minecraft.util.ScreenShotHelper;import org.lwjgl.opengl.GL11;
public final class BagClientChecks {
    private final List<String> report=Collections.synchronizedList(new ArrayList<String>());private int phase,wait=30,age;private boolean done;private volatile boolean failed;
    public void init(){FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    private void pass(String s){report.add("PASS: "+s);}
    private static EntityPlayerMP player(){return (EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
    private void server(Runnable task){ServerWork.enqueue(()->{try{task.run();}catch(Throwable t){failed=true;report.add("FAIL: server :: "+t);IndustrialTechnology.log.error("Bag fixture",t);}});}
    private static void open(int hotbar){EntityPlayerMP p=player();p.inventory.currentItem=hotbar;p.playerNetServerHandler.sendPacket(new S09PacketHeldItemChange(hotbar));p.inventoryContainer.detectAndSendChanges();BagRegistry.bag.onItemRightClick(p.getHeldItem(),p.worldObj,p);}
    private static GuiStorageBag gui(Minecraft mc){check(mc.currentScreen instanceof GuiStorageBag,"bag screen missing");return (GuiStorageBag)mc.currentScreen;}
    private static void shot(Minecraft mc,String name){ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{
        if(failed){finish();return;}
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=3;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.renderDistanceChunks=3;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(270,WorldSettings.GameType.SURVIVAL,false,false,WorldType.FLAT);s.func_82750_a("2;7;1;");mc.launchIntegratedServer("bag-client","Disposable colored bag QA",s);phase=1;wait=70;return;}
        if(mc.thePlayer==null||mc.theWorld==null){if(++age>100)throw new AssertionError("join timeout");wait=10;return;}
        if(phase==1){mc.displayGuiScreen(null);TooltipClientChecks.prepare(mc);server(()->{EntityPlayerMP p=player();p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.playerNetServerHandler.setPlayerLocation(0,75,0,180,0);p.inventory.mainInventory[0]=new ItemStack(BagRegistry.bag,1,11);p.inventory.mainInventory[1]=new ItemStack(BagRegistry.bag,1,11);p.inventory.mainInventory[2]=new ItemStack(BagRegistry.bag,1,14);for(int i=0;i<16;i++)p.inventory.mainInventory[i+9]=new ItemStack(BagRegistry.bag,1,i);ItemStack item=new ItemStack(Items.diamond,23);item.setStackDisplayName("Bag packet diamonds");p.inventory.mainInventory[27]=item;open(0);});phase=2;wait=40;return;}
        if(phase==2){GuiStorageBag g=gui(mc);check(g.bag.inventorySlots.size()==140&&g.bag.getSlot(103).xDisplayPosition==228,"104-slot layout");for(int i=0;i<16;i++)check(BagRegistry.bag.getIconFromDamage(i).getIconName().equals("industrialtech:bags/"+BagRegistry.COLORS[i]),"icon "+i);pass("Original ProjectE atlas aligns all 104 bag slots and 36 player slots; all 16 original colored icons load");mc.playerController.windowClick(g.bag.windowId,122,0,1,mc.thePlayer);phase=3;wait=30;return;}
        if(phase==3){GuiStorageBag g=gui(mc);ItemStack s=g.bag.bag.getStackInSlot(0);check(s!=null&&s.stackSize==23&&s.getDisplayName().equals("Bag packet diamonds")&&!g.bag.getSlot(122).getHasStack(),"shift packet");pass("Real vanilla shift-click packets transfer a named stack into the server bag and synchronize its NBT");mc.playerController.windowClick(g.bag.windowId,103,0,2,mc.thePlayer);mc.playerController.windowClick(g.bag.windowId,g.bag.lockedSlot,0,4,mc.thePlayer);phase=4;wait=30;return;}
        if(phase==4){GuiStorageBag g=gui(mc);check(BagRegistry.valid(mc.thePlayer.getHeldItem())&&g.bag.bag.getStackInSlot(103)==null,"held bag moved");pass("Actual number-key and throw packets cannot move the currently open bag");server(()->{EntityPlayerMP p=player();check(BagRegistry.valid(p.getHeldItem()),"server held bag");BagData.get(p.worldObj).inventory(p.getUniqueID(),11).setInventorySlotContents(103,new ItemStack(Items.gold_ingot,13));p.closeScreen();open(1);});phase=5;wait=35;return;}
        if(phase==5){GuiStorageBag g=gui(mc);check(g.bag.color==11&&g.bag.bag.getStackInSlot(0).stackSize==23&&g.bag.bag.getStackInSlot(103).stackSize==13,"same color storage");shot(mc,"bags-shared-blue.png");pass("A second Blue bag opens the same live inventory, including the visible final slot");server(()->{EntityPlayerMP p=player();p.closeScreen();p.inventory.mainInventory[27]=new ItemStack(Items.iron_ingot,31);open(2);});phase=6;wait=35;return;}
        if(phase==6){GuiStorageBag g=gui(mc);check(g.bag.color==14&&g.bag.bag.getStackInSlot(0)==null&&g.bag.bag.getStackInSlot(103)==null,"color leaked");mc.playerController.windowClick(g.bag.windowId,122,0,1,mc.thePlayer);phase=7;wait=30;return;}
        if(phase==7){GuiStorageBag g=gui(mc);check(g.bag.bag.getStackInSlot(0).getItem()==Items.iron_ingot&&g.bag.bag.getStackInSlot(0).stackSize==31,"red insert");shot(mc,"bags-separate-red.png");pass("Red bag keeps a separate inventory and accepts normal synchronized item transfers");server(()->{EntityPlayerMP p=player();BagInventory b=BagData.get(p.worldObj).inventory(p.getUniqueID(),11);check(b.getStackInSlot(0).getItem()==Items.diamond&&b.getStackInSlot(0).stackSize==23,"blue changed");for(int i=1;i<103;i++)b.setInventorySlotContents(i,new ItemStack(Blocks.stone,64));p.closeScreen();open(0);});phase=8;wait=35;return;}
        if(phase==8){GuiStorageBag g=gui(mc);int full=0;for(int i=0;i<104;i++)if(g.bag.bag.getStackInSlot(i)!=null)full++;check(full==104,"not all slots synchronized");shot(mc,"bags-all-104-slots.png");check(GL11.glGetError()==0,"OpenGL error");pass("All 104 real storage slots render together without pages or overlaps, alongside 16 color variants and NEI; no GL errors");finish();}
    }catch(Throwable t){failed=true;report.add("FAIL: client phase "+phase+" :: "+t);IndustrialTechnology.log.error("Bag client",t);finish();}}
    private void finish(){if(done)return;done=true;try{report.add("Failed: "+(failed?1:0));Files.write(new File(Minecraft.getMinecraft().mcDataDir,"bag-client-report.txt").toPath(),report,StandardCharsets.UTF_8);}catch(Exception e){IndustrialTechnology.log.error("Bag report",e);}Minecraft.getMinecraft().shutdown();}
}
